const markParticipantLeft = `-- name: MarkParticipantLeft :exec
UPDATE giftexchange.participants
SET left_at = GREATEST($1::timestamptz, joined_at)
WHERE exchange_id = $2 AND person_id = $3 AND left_at IS NULL
`

type MarkParticipantLeftParams struct {
	LeftAt     pgtype.Timestamptz
	ExchangeID uuid.UUID
	PersonID   uuid.UUID
}

// GREATEST keeps the participants_left_after_join check true if the clock reads earlier than
// joined_at.
func (q *Queries) MarkParticipantLeft(ctx context.Context, arg MarkParticipantLeftParams) error {
	_, err := q.db.Exec(ctx, markParticipantLeft, arg.LeftAt, arg.ExchangeID, arg.PersonID)
	return err
}

const markRevealReminderSent = `-- name: MarkRevealReminderSent :exec
UPDATE giftexchange.exchanges
SET reveal_reminder_sent_for = $1
WHERE id = $2
`

type MarkRevealReminderSentParams struct {
	SentFor pgtype.Timestamptz
	ID      uuid.UUID
}

func (q *Queries) MarkRevealReminderSent(ctx context.Context, arg MarkRevealReminderSentParams) error {
	_, err := q.db.Exec(ctx, markRevealReminderSent, arg.SentFor, arg.ID)
	return err
}

const reviveParticipant = `-- name: ReviveParticipant :exec
UPDATE giftexchange.participants
SET joined_at = $1, left_at = NULL
WHERE exchange_id = $2 AND person_id = $3
`

type ReviveParticipantParams struct {
	JoinedAt   pgtype.Timestamptz
	ExchangeID uuid.UUID
	PersonID   uuid.UUID
}

// (exchange_id, person_id) is the primary key, so a person who left rejoins by reviving the row.
func (q *Queries) ReviveParticipant(ctx context.Context, arg ReviveParticipantParams) error {
	_, err := q.db.Exec(ctx, reviveParticipant, arg.JoinedAt, arg.ExchangeID, arg.PersonID)
	return err
}

